    private void configurarMenu() {
        javax.swing.JMenuBar barra = new javax.swing.JMenuBar();

        javax.swing.JMenu menuCadastro = new javax.swing.JMenu("Cadastros");
        javax.swing.JMenuItem itemAluno = new javax.swing.JMenuItem("Cadastrar aluno");
        itemAluno.addActionListener(e -> new FormAluno().setVisible(true));
        javax.swing.JMenuItem itemProfessor = new javax.swing.JMenuItem("Cadastrar professor");
        itemProfessor.addActionListener(e -> new FormProfessor().setVisible(true));
        menuCadastro.add(itemAluno);
        menuCadastro.add(itemProfessor);

        javax.swing.JMenu menuConsultas = new javax.swing.JMenu("Consultas");
        javax.swing.JMenuItem consultaAluno = new javax.swing.JMenuItem("Consultar / editar alunos");
        consultaAluno.addActionListener(e -> new FormConsultaAluno().setVisible(true));
        javax.swing.JMenuItem consultaProfessor = new javax.swing.JMenuItem("Consultar / editar professores");
        consultaProfessor.addActionListener(e -> new FormConsultaProfessor().setVisible(true));
        menuConsultas.add(consultaAluno);
        menuConsultas.add(consultaProfessor);

        javax.swing.JMenu menuSistema = new javax.swing.JMenu("Sistema");
        javax.swing.JMenuItem sair = new javax.swing.JMenuItem("Sair");
        sair.addActionListener(e -> System.exit(0));
        menuSistema.add(sair);

        barra.add(menuCadastro);
        barra.add(menuConsultas);
        barra.add(menuSistema);
        setJMenuBar(barra);
    }

